def process(path):
    rows = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 3:
                continue
            name, qty, price = parts
            try:
                qty = int(qty); price = float(price)
            except ValueError:
                continue
            rows.append((name, qty, price))
    total = 0.0
    for name, qty, price in rows:
        total += qty * price
    top = sorted(rows, key=lambda r: r[1] * r[2], reverse=True)[:3]
    print(f"total={total:.2f}")
    for name, qty, price in top:
        print(f"{name}: {qty * price:.2f}")
    return total

Write pytest tests for this function. Cover the normal case, an empty list, a list with a single element, negative numbers, and the claim that the result never mutates the input.

def normalize(xs: list[float]) -> list[float]:
    if not xs:
        return []
    lo, hi = min(xs), max(xs)
    if hi == lo:
        return [0.0 for _ in xs]
    return [(x - lo) / (hi - lo) for x in xs]
